51	/** Pinned Adminer single-file build dropped into an account webroot for the DB
52	 *  manager. Pinned (not "latest") like the one-click app recipes so the artifact
53	 *  is deterministic. */
54	const ADMINER_URL = "https://github.com/vrana/adminer/releases/download/v4.8.1/adminer-4.8.1.php";
55	
56	/** Shell-escape the raw SQL from buildScopedGrantSql for embedding in a
57	 *  double-quoted `mysql -e "..."`. Identifiers/passwords are already validated
58	 *  to safe charsets; only the SQL's own backticks need escaping so the shell
59	 *  doesn't treat them as command substitution. */
60	function sqlForMysqlExec(sql: string): string {
61	  return sql.replace(/`/g, "\\`");
62	}
63	
64	const ENABLED = process.env.ENABLE_SHARED_HOSTING === "1";
65	const CONNECT_TIMEOUT_MS = 20_000;
66	const STEP_TIMEOUT_MS = 60_000;
67	
68	/** Alphanumeric password (shell/SQL-safe: no quoting hazards). */
69	function strongPassword(len = 22): string {
70	  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
71	  const bytes = randomBytes(len);
72	  let out = "";
73	  for (let i = 0; i < len; i++) out += alphabet[bytes[i] % alphabet.length];
74	  return out;
75	}
76	
77	async function connectNode(node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null }): Promise<Client> {
78	  const password = node.rootPasswordEnc ? decryptSecret(node.rootPasswordEnc) : "";
79	  if (!password) throw new Error("Hosting node has no root credential on record.");
80	  const conn = new Client();
81	  await new Promise<void>((resolve, reject) => {
82	    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
83	    conn
84	      .on("ready", () => { clearTimeout(timer); resolve(); })
85	      .on("error", (e) => { clearTimeout(timer); reject(e); })
86	      .connect({ host: node.sshHost, port: node.sshPort, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
87	  });
88	  return conn;
89	}
90	
91	function exec(conn: Client, command: string, timeoutMs = STEP_TIMEOUT_MS): Promise<{ code: number; out: string }> {
92	  return new Promise((resolve, reject) => {
93	    const timer = setTimeout(() => reject(new Error("command timed out")), timeoutMs);
94	    conn.exec(command, (err, stream) => {
95	      if (err) { clearTimeout(timer); return reject(err); }
96	      let out = "";
97	      stream
98	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, out }); })
99	        .on("data", (d: Buffer) => { out += d.toString(); })
100	        .stderr.on("data", (d: Buffer) => { out += d.toString(); });
101	    });
102	  });
103	}
104	
105	async function run(conn: Client, label: string, cmd: string): Promise<void> {
106	  const r = await exec(conn, cmd, STEP_TIMEOUT_MS);
107	  if (r.code !== 0) throw new Error(`${label} failed: ${r.out.slice(0, 300)}`);
108	}
