110	/**
111	 * The name-based nginx vhost for one account. It ALWAYS emits a `listen 443 ssl`
112	 * server block so nginx answers HTTPS from the moment the account exists —
113	 * `ssl.certDir` is the real Let's Encrypt live dir when `ssl.real` is true, else
114	 * the per-account SELF-SIGNED fallback generated at provision time. That is the
115	 * whole "clean setup always" guarantee: HTTPS shows a cert WARNING, never
116	 * ERR_CONNECTION_REFUSED. The HTTP→HTTPS redirect fires ONLY once a real cert
117	 * exists; a self-signed site still serves its body over both 80 and 443 (so it
118	 * can't 301-loop a visitor into an untrusted-cert dead end). Shared IP; routed
119	 * purely by server_name; PHP proxied to THIS account's socket only, root jailed to
120	 * its webroot. Pure string — no interpolation reaches a shell here.
121	 */
122	function renderHostingVhost(username: string, domain: string, webroot: string, sock: string, ssl: { certDir: string; real: boolean }): string {
123	  const phpLoc = [
124	    `    location ~ \\.php$ {`,
125	    `        include fastcgi_params;`,
126	    `        fastcgi_pass unix:${sock};`,
127	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
128	    `    }`,
129	  ].join("\n");
130	  const body = [
131	    `    root ${webroot};`,
132	    // Refuse to follow a symlink whose target isn't owned by the same user as the
133	    // link — blocks a tenant symlinking to a victim's wp-config.php that nginx
134	    // (www-data) would otherwise happily serve (cross-tenant read, audit CRITICAL-1).
135	    `    disable_symlinks if_not_owner;`,
136	    `    index index.php index.html;`,
137	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
138	    phpLoc,
139	    `    location ~ /\\. { deny all; }`,
140	  ].join("\n");
141	  const http = [
142	    `server {`,
143	    `    listen 80;`,
144	    `    listen [::]:80;`,
145	    `    server_name ${domain} www.${domain};`,
146	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
147	    // Redirect to HTTPS only with a REAL cert; a self-signed site serves over 80 too.
148	    ssl.real ? `    location / { return 301 https://$host$request_uri; }` : body,
149	    `}`,
150	  ].join("\n");
151	  const https = [
152	    `server {`,
153	    `    listen 443 ssl;`,
154	    `    listen [::]:443 ssl;`,
155	    `    server_name ${domain} www.${domain};`,
156	    `    ssl_certificate ${ssl.certDir}/fullchain.pem;`,
157	    `    ssl_certificate_key ${ssl.certDir}/privkey.pem;`,
158	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
159	    body,
160	    `}`,
161	  ].join("\n");
162	  return `${http}\n${https}\n`;
163	}
164	
165	/** Write a vhost file + enable it, tested before reload. */
166	async function installVhost(conn: Client, username: string, conf: string): Promise<void> {
167	  const path = `/etc/nginx/sites-available/hosting-${username}.conf`;
168	  await run(conn, "write vhost", `cat > ${path} <<'VH'\n${conf}VH\nln -sfn ${path} /etc/nginx/sites-enabled/hosting-${username}.conf`);
169	  await run(conn, "test + reload nginx", `nginx -t && systemctl reload nginx`);
170	}
171	
172	/**
173	 * A single extra site (subdomain / addon domain): its own docroot + PHP socket,
174	 * one `server_name`. Same shape as renderHostingVhost but keyed on an explicit
175	 * server_name string so it can serve a subdomain OR an addon domain. Pure — no
176	 * interpolation reaches a shell here (the caller validated every part).
177	 */
178	function renderSiteVhost(serverName: string, docroot: string, sock: string, sslLiveDir: string | null): string {
179	  const phpLoc = [
180	    `    location ~ \\.php$ {`,
181	    `        include fastcgi_params;`,
182	    `        fastcgi_pass unix:${sock};`,
183	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
184	    `    }`,
185	  ].join("\n");
186	  const body = [
187	    `    root ${docroot};`,
188	    // Refuse a symlink whose target isn't owned by the link's owner — a tenant
189	    // can't symlink a neighbour's file into a served path (audit CRITICAL-1).
190	    `    disable_symlinks if_not_owner;`,
191	    `    index index.php index.html;`,
192	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
193	    phpLoc,
194	    `    location ~ /\\. { deny all; }`,
195	  ].join("\n");
196	  const http = [
197	    `server {`,
198	    `    listen 80;`,
199	    `    listen [::]:80;`,
200	    `    server_name ${serverName};`,
201	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
202	    sslLiveDir ? `    location / { return 301 https://$host$request_uri; }` : body,
203	    `}`,
204	  ].join("\n");
205	  if (!sslLiveDir) return http + "\n";
206	  const https = [
207	    `server {`,
208	    `    listen 443 ssl;`,
209	    `    listen [::]:443 ssl;`,
210	    `    server_name ${serverName};`,
211	    `    ssl_certificate ${sslLiveDir}/fullchain.pem;`,
212	    `    ssl_certificate_key ${sslLiveDir}/privkey.pem;`,
213	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
214	    body,
215	    `}`,
216	  ].join("\n");
217	  return `${http}\n${https}\n`;
218	}
219	
220	/** Write + enable a vhost under an arbitrary key (hosting-<key>.conf), tested
221	 *  before reload. Used for subdomain / addon-domain sites (key = <user>-<label>
222	 *  or <user>-<domain>); the account's own primary vhost keeps its <user> filename. */
223	async function installNamedVhost(conn: Client, key: string, conf: string): Promise<void> {
224	  const path = `/etc/nginx/sites-available/hosting-${key}.conf`;
225	  await run(conn, "write site vhost", `cat > ${path} <<'VH'\n${conf}VH\nln -sfn ${path} /etc/nginx/sites-enabled/hosting-${key}.conf`);
226	  await run(conn, "test + reload nginx", `nginx -t && systemctl reload nginx`);
227	}
228	
229	/** Remove a named site vhost (enabled + available), tested before reload. */
230	async function removeNamedVhost(conn: Client, key: string): Promise<void> {
231	  await run(conn, "remove site vhost", `rm -f /etc/nginx/sites-enabled/hosting-${key}.conf /etc/nginx/sites-available/hosting-${key}.conf; nginx -t && systemctl reload nginx || true`);
232	}
233	
234	/** Write + (re)load an account's FPM pool for a given PHP version. The pool
235	 *  contents (the PHP isolation boundary) come from the tested pure generator in
236	 *  lib/hosting.ts — socket path is unchanged across versions so the vhost never
237	 *  needs editing when PHP is switched. */
238	async function writeFpmPool(conn: Client, u: string, home: string, webroot: string, php: string): Promise<void> {
239	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
240	  await run(conn, "php-fpm pool", `cat > /etc/php/${php}/fpm/pool.d/${u}.conf <<'POOL'\n${fpmPoolConfig(u, home, webroot)}\nPOOL\nsystemctl reload php${php}-fpm 2>/dev/null || systemctl restart php${php}-fpm`);
241	}
242	
243	/**
244	 * The isolation shell for one account (HTTP-only vhost; SSL added later by the
245	 * sweep once DNS points at us). Every interpolated value has already cleared a
246	 * validator, so nothing here can be a shell metacharacter.
247	 */
248	async function applyIsolation(
249	  conn: Client,
250	  a: { username: string; primaryDomain: string; diskQuotaMB: number; sftpPassword: string },
251	  php: string,
252	): Promise<void> {
253	  const u = a.username;
254	  const d = a.primaryDomain;
255	  if (!isValidUnixUsername(u)) throw new Error(`refusing unsafe username ${u}`);
256	  if (!isValidHostingDomain(d)) throw new Error(`refusing unsafe domain ${d}`);
257	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
258	  const { home, webroot } = accountPaths(u);
259	  const quotaGB = Math.max(1, Math.round(a.diskQuotaMB / 1024));
260	  const hardBlocks = diskQuotaBlocks(quotaGB);
261	  const softBlocks = Math.floor(hardBlocks * 0.95);
262	  const inodes = diskQuotaInodes(quotaGB);
263	  const sock = `/run/php/${u}.sock`;
264	
265	  // 1. Jailed user. Home is ROOT-owned (a chroot requirement); the user owns only
266	  //    public_html + tmp under it. nologin shell — SFTP-only via the chroot below.
267	  //
268	  // Perms come from the tested accountFsPlan(): home 711 (chroot-safe + nginx can
269	  // TRAVERSE to the webroot but a peer tenant can't LIST the home), webroot
270	  // 2750 <user>:www-data (nginx reads via the www-data GROUP, never world — the
271	  // old world-readable 755 let any tenant read a neighbour's wp-config.php if
272	  // open_basedir was escaped; the setgid bit keeps tenant-created files in the
273	  // www-data group so nginx keeps serving them), tmp 700 (private PHP scratch).
274	  const fs = accountFsPlan(u);
275	  await run(conn, "create user", `id -u ${u} >/dev/null 2>&1 || useradd -m -d ${home} -s /usr/sbin/nologin ${u}`);
276	  await run(
277	    conn,
278	    "chroot-safe home",
279	    `mkdir -p ${webroot} ${home}/tmp && ` +
280	      `chown ${fs.home.owner} ${home} && chmod ${fs.home.mode} ${home} && ` +
281	      `chown ${fs.webroot.owner} ${webroot} && chmod ${fs.webroot.mode} ${webroot} && ` +
282	      `chown ${fs.tmp.owner} ${home}/tmp && chmod ${fs.tmp.mode} ${home}/tmp`,
283	  );
284	  await run(conn, "sftp password", `printf '%s:%s' ${u} '${a.sftpPassword}' | chpasswd`);
285	
286	  // 2. Disk quota (fs must have usrquota — node onboarding enables it). The last
287	  //    two fields are the INODE soft/hard limits: `0 0` = unlimited inodes, which
288	  //    let a tenant exhaust the shared filesystem's inode table with millions of
289	  //    tiny files (a DoS the block quota can't stop), so we pass real caps (HIGH-2).
290	  await run(conn, "disk quota", `command -v setquota >/dev/null 2>&1 && setquota -u ${u} ${softBlocks} ${hardBlocks} ${inodes.soft} ${inodes.hard} /home || echo 'quota tool absent — skipped'`);
291	
292	  // 3. Per-user PHP-FPM pool — THE PHP isolation boundary.
293	  await writeFpmPool(conn, u, home, webroot, php);
294	
295	  // 4. Self-signed FALLBACK cert, so nginx can listen on 443 from the very first
296	  //    second the account exists. Without this the account served HTTP-only until
297	  //    the SSL sweep ran, and any visitor hitting https:// got ERR_CONNECTION_REFUSED
298	  //    while the panel already said "active" (the kaymo failure). Idempotent: only
299	  //    generated if absent. Key is 600 root; the whole dir is root-owned + off the
300	  //    tenant tree, so a tenant can never read or swap its own TLS key.
301	  const ssCertDir = selfSignedCertDir(u);
302	  await run(
303	    conn,
304	    "self-signed fallback cert",
305	    `mkdir -p ${ssCertDir} && chmod 700 ${ssCertDir} && ` +
306	      `if [ ! -s ${ssCertDir}/fullchain.pem ] || [ ! -s ${ssCertDir}/privkey.pem ]; then ` +
307	      `openssl req -x509 -newkey rsa:2048 -nodes -keyout ${ssCertDir}/privkey.pem -out ${ssCertDir}/fullchain.pem ` +
308	      `-days 3650 -subj "/CN=${d}" -addext "subjectAltName=DNS:${d},DNS:www.${d}"; fi && ` +
309	      `chown -R root:root ${ssCertDir} && chmod 600 ${ssCertDir}/privkey.pem && chmod 644 ${ssCertDir}/fullchain.pem`,
310	  );
311	
312	  // 5. Name-based vhost — ALWAYS listens on 443, using the self-signed fallback
313	  //    until the SSL sweep swaps in the real Let's Encrypt cert.
314	  await installVhost(conn, u, renderHostingVhost(u, d, webroot, sock, { certDir: ssCertDir, real: false }));
315	
316	  // 6. Chrooted SFTP — sshd -t GUARDED so a bad config can never lock out the box.
317	  const sftpConf = [
318	    `Match User ${u}`,
319	    `    ChrootDirectory ${home}`,
320	    `    ForceCommand internal-sftp`,
321	    `    AllowTcpForwarding no`,
322	    `    X11Forwarding no`,
323	  ].join("\n");
324	  const sshdFile = `/etc/ssh/sshd_config.d/nxeon-${u}.conf`;
325	  await run(
326	    conn,
327	    "sftp chroot (guarded)",
328	    // Write to a temp include, validate the WHOLE sshd config, and only then move
329	    // it into place + reload. If sshd -t fails, discard — never reload a broken config.
330	    `mkdir -p /etc/ssh/sshd_config.d && cat > ${sshdFile}.new <<'SSHD'\n${sftpConf}\nSSHD\n` +
331	      `cp -f ${sshdFile}.new ${sshdFile} && if sshd -t 2>/dev/null; then systemctl reload ssh 2>/dev/null || systemctl reload sshd; else rm -f ${sshdFile}; echo 'sshd -t rejected the chroot block — SFTP not enabled, box untouched'; fi; rm -f ${sshdFile}.new`,
332	  );
333	}
334	
335	// ---- DB provisioning (per-account, on demand) ------------------------------
336	
337	/** Create ONE scoped MySQL/MariaDB user+db on the account's node. */
338	async function provisionHostingDatabase(dbId: string): Promise<void> {
339	  const rec = await db.hostingDatabase.findUnique({ where: { id: dbId }, include: { account: { include: { node: true } } } });
340	  if (!rec || rec.status !== "PENDING") return;
341	  if (SANDBOX || !ENABLED) {
342	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: SANDBOX ? "ACTIVE" : "PENDING", passwordEnc: null, error: SANDBOX ? null : "Shared hosting not enabled." } });
343	    return;
344	  }
345	  const name = rec.name;
346	  const user = rec.dbUser;
347	  const pass = rec.passwordEnc ? decryptSecret(rec.passwordEnc) : "";
348	  // DB name + user were built from the validated username; re-assert shape.
349	  if (!/^[a-z0-9_]{1,64}$/.test(name) || !/^[a-z0-9_]{1,32}$/.test(user) || !pass) {
350	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: "invalid db identifiers" } });
351	    return;
352	  }
353	  try {
354	    const conn = await connectNode(rec.account.node);
355	    try {
356	      // Grants scoped to THIS database only — the data-isolation boundary.
357	      // buildScopedGrantSql escapes _/% so the GRANT can't bleed onto a peer's db.
358	      const sql = sqlForMysqlExec(buildScopedGrantSql(name, user, pass));
359	      await run(conn, "create database", `mysql -e "${sql}"`);
360	    } finally {
361	      try { conn.end(); } catch { /* */ }
362	    }
363	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "ACTIVE", passwordEnc: null, error: null } });
364	  } catch (e) {
365	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
366	  }
367	}
368	
369	export async function hostingDatabaseSweep(): Promise<void> {
370	  const pending = await db.hostingDatabase.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 10 });
371	  for (const p of pending) await provisionHostingDatabase(p.id).catch((e) => console.error(`[hosting] db ${p.id} failed`, e));
372	}
373	
374	// ---- Account provisioning --------------------------------------------------
375	
376	export async function provisionHostingAccount(accountId: string): Promise<void> {
377	  const account = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { node: true, plan: true } });
378	  if (!account || account.status !== "PENDING") return;
379	  await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PROVISIONING", error: null } });
380	
381	  if (SANDBOX || !ENABLED) {
382	    if (SANDBOX) {
383	      const pw = strongPassword();
384	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(pw), error: null } });
385	    } else {
386	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PENDING", error: "Shared hosting is not enabled on this deployment yet." } });
387	    }
388	    return;
389	  }
390	
391	  try {
392	    const allowed = planLimits(account.plan).phpVersions;
393	    const php = allowed.includes(account.phpVersion) ? account.phpVersion : allowed[0];
394	    const sftpPassword = strongPassword();
395	    const conn = await connectNode(account.node);
396	    try {
397	      await applyIsolation(conn, { username: account.username, primaryDomain: account.primaryDomain, diskQuotaMB: account.diskQuotaMB, sftpPassword }, php);
398	    } finally {
399	      try { conn.end(); } catch { /* */ }
400	    }
401	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(sftpPassword), error: null } });
402	  } catch (e) {
403	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
404	  }
405	}
406	
407	export async function hostingProvisionSweep(): Promise<void> {
408	  const pending = await db.hostingAccount.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 10 });
