414	/** True once `domain` resolves (A) to the node's shared IP — DNS is pointed at us. */
415	async function domainPointsAt(domain: string, ip: string): Promise<boolean> {
416	  try {
417	    const a = await dns.resolve4(domain);
418	    return a.includes(ip);
419	  } catch {
420	    return false;
421	  }
