424	/**
425	 * For each ACTIVE account without HTTPS, once its domain resolves to the node's
426	 * shared IP, issue a per-domain cert (webroot) and upgrade the vhost to a 443 SNI
427	 * block. Safe: touches only nginx + certbot, never sshd.
428	 */
429	export async function hostingSslSweep(): Promise<void> {
430	  if (SANDBOX || !ENABLED) return;
431	  const accts = await db.hostingAccount.findMany({
432	    where: { status: "ACTIVE", sslActive: false },
433	    include: { node: true },
434	    take: 20,
435	  });
436	  for (const a of accts) {
437	    try {
438	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
439	      if (!(await domainPointsAt(a.primaryDomain, a.node.publicIp))) continue; // DNS not pointed yet
440	      const d = a.primaryDomain;
441	      const conn = await connectNode(a.node);
442	      try {
443	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html -d ${d} -d www.${d} --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
444	        const liveDir = `/etc/letsencrypt/live/${d}`;
445	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
446	        if (have.out.trim() !== "yes") { console.log(`[hosting] cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
447	        const { webroot } = accountPaths(a.username);
448	        await installVhost(conn, a.username, renderHostingVhost(a.username, d, webroot, `/run/php/${a.username}.sock`, { certDir: liveDir, real: true }));
449	      } finally {
450	        try { conn.end(); } catch { /* */ }
451	      }
452	      await db.hostingAccount.update({ where: { id: a.id }, data: { sslActive: true } });
453	      console.log(`[hosting] HTTPS active for ${a.primaryDomain}`);
454	    } catch (e) {
455	      console.error(`[hosting] ssl sweep ${a.id} failed`, e);
456	    }
457	  }
458	
459	  // Addon domains get their own per-domain cert the same way, once they resolve
460	  // to the node's shared IP. (Subdomains are folded into the account cert below.)
461	  const addons = await db.hostingAddonDomain.findMany({
462	    where: { status: "ACTIVE", sslActive: false },
463	    include: { account: { include: { node: true } } },
464	    take: 20,
465	  });
466	  for (const ad of addons) {
467	    try {
468	      const u = ad.account.username;
469	      const d = ad.domain;
470	      if (!isValidHostingDomain(d) || !isValidUnixUsername(u)) continue;
471	      if (!(await domainPointsAt(d, ad.account.node.publicIp))) continue; // DNS not pointed yet
472	      const conn = await connectNode(ad.account.node);
473	      try {
474	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html -d ${d} -d www.${d} --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
475	        const liveDir = `/etc/letsencrypt/live/${d}`;
476	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
477	        if (have.out.trim() !== "yes") { console.log(`[hosting] addon cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
478	        const { docroot } = addonDomainPaths(u, d);
479	        await installNamedVhost(conn, `${u}-${d}`, renderSiteVhost(`${d} www.${d}`, docroot, `/run/php/${u}.sock`, liveDir));
480	      } finally {
481	        try { conn.end(); } catch { /* */ }
482	      }
483	      await db.hostingAddonDomain.update({ where: { id: ad.id }, data: { sslActive: true } });
484	      console.log(`[hosting] HTTPS active for addon ${d}`);
485	    } catch (e) {
486	      console.error(`[hosting] addon ssl sweep ${ad.id} failed`, e);
487	    }
488	  }
489	
490	  // Subdomains: fold each into its ACCOUNT'S existing Let's Encrypt cert as an
491	  // extra SAN once it resolves to the node, then serve 443 for it off that same
492	  // live dir. We reuse the account cert (HTTP-01 webroot, --expand) rather than a
493	  // wildcard: a wildcard needs DNS-01 + a DNS-provider API we don't hold (customers
494	  // self-manage their DNS), whereas SAN expansion works off the pointed A record —
495	  // the same flow every other cert here uses. The subdomain's HTTP vhost already
496	  // proxies /.well-known/acme-challenge to /var/www/html, so the challenge serves.
497	  const pendingSubs = await db.hostingSubdomain.findMany({
498	    where: { status: "ACTIVE", sslActive: false },
499	    include: { account: { include: { node: true } } },
500	    take: 30,
501	  });
502	  // One reissue per account per sweep even if several of its subdomains are pending
503	  // — the reissue covers them all at once, and each is verified independently below.
504	  const seenAccounts = new Set<string>();
505	  for (const sub of pendingSubs) {
506	    if (seenAccounts.has(sub.accountId)) continue;
507	    seenAccounts.add(sub.accountId);
508	    try {
509	      const a = sub.account;
510	      const u = a.username;
511	      const primary = a.primaryDomain;
512	      if (!isValidHostingDomain(primary) || !isValidUnixUsername(u)) continue;
513	      const liveDir = `/etc/letsencrypt/live/${primary}`;
514	      // All ACTIVE subdomains of this account, and which of them already resolve to
515	      // us. Only names that resolve are folded in, so certbot never churns on a name
516	      // it can't validate and the SAN set stays stable between ticks (idempotent).
517	      const active = await db.hostingSubdomain.findMany({ where: { accountId: a.id, status: "ACTIVE" } });
518	      const resolving: typeof active = [];
519	      for (const s of active) {
520	        if (!isValidSubdomainLabel(s.label)) continue;
521	        const fqdn = `${s.label}.${primary}`;
522	        if (!isValidHostingDomain(fqdn)) continue;
523	        if (await domainPointsAt(fqdn, a.node.publicIp)) resolving.push(s);
524	      }
525	      // Nothing to do until at least one not-yet-secured subdomain resolves to us.
526	      if (!resolving.some((s) => !s.sslActive)) continue;
527	      const conn = await connectNode(a.node);
528	      try {
529	        // The account cert must already exist (the primary sweep mints it once the
530	        // primary resolves). If it doesn't yet, leave it to that sweep and retry.
531	        if ((await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`)).out.trim() !== "yes") continue;
532	        // SAN set = primary + www + every already-secured sub (never drop a live one)
533	        // + every currently-resolving sub. --cert-name pins the lineage to <primary>
534	        // so the live dir path is stable; --expand folds in the new SANs; --allow-
535	        // subset-of-names keeps a name that isn't pointed from aborting the cert;
536	        // --keep-until-expiring makes a no-op reissue idempotent when nothing changed.
537	        const keep = active.filter(
538	          (s) => (s.sslActive || resolving.includes(s)) && isValidSubdomainLabel(s.label) && isValidHostingDomain(`${s.label}.${primary}`),
539	        );
540	        const dflags = [primary, `www.${primary}`, ...keep.map((s) => `${s.label}.${primary}`)].map((n) => `-d ${n}`).join(" ");
541	        await exec(
542	          conn,
543	          `certbot certonly --webroot -w /var/www/html --cert-name ${primary} ${dflags} --expand --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`,
544	          3 * 60_000,
545	        );
546	        // The reissue rewrote the cert in place. For each newly-securable sub, confirm
547	        // the cert now actually carries it as a SAN (a name whose challenge failed was
548	        // dropped by --allow-subset-of-names), then serve 443 for it off the account
549	        // live dir — installNamedVhost's nginx reload also loads the expanded cert.
550	        for (const s of resolving) {
551	          if (s.sslActive) continue; // already serving HTTPS — leave it untouched
552	          const fqdn = `${s.label}.${primary}`;
553	          const covered = (await exec(conn, `openssl x509 -in ${liveDir}/fullchain.pem -noout -text 2>/dev/null | grep -qiF 'DNS:${fqdn}' && echo yes || echo no`)).out.trim() === "yes";
554	          if (!covered) { console.log(`[hosting] subdomain ${fqdn} not yet in cert — retrying next tick`); continue; }
555	          const { docroot } = subdomainPaths(u, s.label);
556	          await installNamedVhost(conn, `${u}-${s.label}`, renderSiteVhost(fqdn, docroot, `/run/php/${u}.sock`, liveDir));
557	          await db.hostingSubdomain.update({ where: { id: s.id }, data: { sslActive: true } });
558	          console.log(`[hosting] HTTPS active for subdomain ${fqdn}`);
559	        }
560	      } finally {
561	        try { conn.end(); } catch { /* */ }
562	      }
563	    } catch (e) {
564	      console.error(`[hosting] subdomain ssl sweep ${sub.accountId} failed`, e);
565	    }
566	  }
567	}
