601	// ---- Serve-verification + self-heal health sweep ---------------------------
602	
603	/** Parse the numeric HTTP status curl printed with `-w '%{http_code}'`. Returns 0
604	 *  when curl couldn't get a response (connection refused/timeout → "000"). */
605	function parseHttpCode(out: string): number {
606	  const n = parseInt(out.trim().slice(-3), 10);
607	  return Number.isFinite(n) ? n : 0;
608	}
609	/** A 2xx/3xx means nginx actually answered with a page/redirect for this vhost —
610	 *  the anti-ERR_CONNECTION_REFUSED signal. 4xx/5xx/000 are NOT counted as serving
611	 *  (we never mark an account falsely healthy). */
612	function servesOk(code: number): boolean {
613	  return code >= 200 && code < 400;
614	}
615	
616	/**
617	 * Serve-verification + self-heal for ACTIVE accounts. From the node itself it
618	 * curls http/https for each account's own Host header and records whether nginx
619	 * genuinely answers on 80/443 (serveHttpOk / serveHttpsOk) — so the panel reflects
620	 * REALITY, never "active" while HTTPS refuses (the kaymo failure). It also
621	 * SELF-HEALS: if a real Let's Encrypt cert exists but 443 isn't serving, it
622	 * reinstalls the real-cert vhost and reloads nginx; if HTTPS just isn't issued yet
623	 * it's left to hostingSslSweep. Gated ENABLED && !SANDBOX like every other node
624	 * path. `onlyRequested` processes just the accounts a customer clicked "Check now"
625	 * on (recheckRequested), so the button feels immediate; the full sweep runs on the
626	 * ~10-min tick. Returns the number of accounts processed.
627	 */
628	export async function hostingHealthSweep(opts: { onlyRequested?: boolean } = {}): Promise<number> {
629	  const onlyRequested = opts.onlyRequested === true;
630	  if (SANDBOX) {
631	    // Simulate a healthy check so the dev panel + the "Check now" button resolve,
632	    // and the recheck flag clears. HTTPS "verified" mirrors the (simulated) sslActive.
633	    const accts = await db.hostingAccount.findMany({
634	      where: onlyRequested ? { status: "ACTIVE", recheckRequested: true } : { status: "ACTIVE" },
635	      select: { id: true, sslActive: true },
636	      take: onlyRequested ? 25 : 50,
637	    });
638	    for (const a of accts) {
639	      await db.hostingAccount.update({
640	        where: { id: a.id },
641	        data: {
642	          serveHttpOk: true,
643	          serveHttpsOk: true,
644	          healthNote: a.sslActive ? "HTTPS live — verified" : "HTTP live, HTTPS issuing",
645	          healthCheckedAt: new Date(),
646	          recheckRequested: false,
647	        },
648	      }).catch(() => undefined);
649	    }
650	    return accts.length;
651	  }
652	  if (!ENABLED) return 0;
653	
654	  const accts = await db.hostingAccount.findMany({
655	    where: onlyRequested ? { status: "ACTIVE", recheckRequested: true } : { status: "ACTIVE" },
656	    include: { node: true },
657	    // Newest-requested first so a customer who just clicked "Check now" is served
658	    // before the routine backlog even in the full sweep.
659	    orderBy: [{ recheckRequested: "desc" }, { updatedAt: "asc" }],
660	    take: onlyRequested ? 25 : 30,
661	  });
662	  let processed = 0;
663	  for (const a of accts) {
664	    try {
665	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
666	      const d = a.primaryDomain;
667	      const u = a.username;
668	      let serveHttpOk = false;
669	      let serveHttpsOk = false;
670	      let sslActive = a.sslActive;
671	      let note = "";
672	      const conn = await connectNode(a.node);
673	      try {
674	        const httpR = await exec(conn, `curl -s -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' http://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
675	        const httpsR = await exec(conn, `curl -sk -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' https://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
676	        serveHttpOk = servesOk(parseHttpCode(httpR.out));
677	        serveHttpsOk = servesOk(parseHttpCode(httpsR.out));
678	
679	        // Does a REAL Let's Encrypt cert exist on the node for this domain?
680	        const liveDir = `/etc/letsencrypt/live/${d}`;
681	        const haveReal = (await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`)).out.trim() === "yes";
682	
683	        // SELF-HEAL: a real cert exists but 443 isn't serving → the vhost is stale
684	        // or nginx dropped the block. Reinstall the real-cert vhost + reload, then
685	        // re-verify. This is the recovery from exactly the state kaymo hit.
686	        if (haveReal && !serveHttpsOk) {
687	          const { webroot } = accountPaths(u);
688	          try {
689	            await installVhost(conn, u, renderHostingVhost(u, d, webroot, `/run/php/${u}.sock`, { certDir: liveDir, real: true }));
690	            const reR = await exec(conn, `curl -sk -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' https://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
691	            serveHttpsOk = servesOk(parseHttpCode(reR.out));
692	            if (serveHttpsOk) note = "Recovered HTTPS (reinstalled certificate vhost)";
693	          } catch (e) {
694	            note = "HTTPS repair failed — support notified";
695	            console.error(`[hosting] health self-heal ${a.id} failed`, e);
696	          }
697	        }
698	        if (haveReal && serveHttpsOk) sslActive = true; // real cert is live
699	
700	        if (!note) {
701	          if (sslActive && serveHttpsOk) note = "HTTPS live — verified";
702	          else if (serveHttpsOk || serveHttpOk) note = "HTTP live, HTTPS issuing";
703	          else {
704	            // Nothing served locally. If DNS isn't pointed at us yet, say so;
705	            // otherwise it's a serving fault the SSL sweep / support will chase.
706	            const pointed = await domainPointsAt(d, a.node.publicIp);
707	            note = pointed ? "Serving issue — being checked" : "DNS not detected yet";
708	          }
709	        }
710	      } finally {
711	        try { conn.end(); } catch { /* */ }
712	      }
713	      await db.hostingAccount.update({
714	        where: { id: a.id },
715	        data: { serveHttpOk, serveHttpsOk, sslActive, healthNote: note.slice(0, 200), healthCheckedAt: new Date(), recheckRequested: false },
716	      });
717	      processed++;
718	    } catch (e) {
719	      console.error(`[hosting] health sweep ${a.id} failed`, e);
720	      // Clear the recheck flag even on failure so a broken node can't wedge the
721	      // fast path into re-processing the same account every 30s forever.
722	      await db.hostingAccount.update({ where: { id: a.id }, data: { recheckRequested: false } }).catch(() => undefined);
723	    }
724	  }
725	  return processed;
726	}
