737	/** Move an account's FPM pool to a new PHP version (socket path is unchanged, so
738	 *  the vhost never needs editing). */
739	async function taskPhpSwitch(conn: Client, a: { id: string; username: string; phpVersion: string }, payload: string | null): Promise<void> {
740	  const version = String(JSON.parse(payload || "{}").version ?? "");
741	  if (!/^\d\.\d$/.test(version)) throw new Error("invalid php version");
742	  const { home, webroot } = accountPaths(a.username);
743	  if (version !== a.phpVersion) {
744	    await run(conn, "remove old pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
745	  }
746	  await writeFpmPool(conn, a.username, home, webroot, version);
747	  await db.hostingAccount.update({ where: { id: a.id }, data: { phpVersion: version } });
748	}
