750	// ---- Account lifecycle (suspend / unsuspend / terminate) --------------------
751	// All three validate the username first (it flows into shell), and are written to
752	// be idempotent + safe to re-run. They only touch this account's own files.
753	
754	type LifecycleAccount = { id: string; username: string; phpVersion: string };
755	
756	// Validate BOTH shell-bound fields up front. username is a strict allowlist;
757	// phpVersion is stored (schema default "8.3") but re-checked here so it can never
758	// carry anything but `\d.\d` into an `rm`/`systemctl` line (security audit LOW-1).
759	function assertLifecycleSafe(a: LifecycleAccount): void {
760	  if (!isValidUnixUsername(a.username)) throw new Error("unsafe account username");
761	  if (!/^\d\.\d$/.test(a.phpVersion)) throw new Error("unsafe php version");
762	}
763	
764	/** Take an account OFFLINE without destroying data: drop the nginx site, remove
765	 *  the FPM pool (no PHP), and lock the unix user (no SFTP/login). Reversible. */
766	async function taskSuspend(conn: Client, a: LifecycleAccount): Promise<void> {
767	  assertLifecycleSafe(a);
768	  await run(conn, "suspend: disable vhost", `rm -f /etc/nginx/sites-enabled/hosting-${a.username}.conf; nginx -t && systemctl reload nginx || true`);
769	  await run(conn, "suspend: remove fpm pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
770	  await run(conn, "suspend: lock user", `usermod -L ${a.username} 2>/dev/null || true; pkill -u ${a.username} 2>/dev/null || true`);
771	}
772	
773	/** Reverse a suspend: re-enable the site, rebuild the FPM pool, unlock the user. */
774	async function taskUnsuspend(conn: Client, a: LifecycleAccount): Promise<void> {
775	  assertLifecycleSafe(a);
776	  const { home, webroot } = accountPaths(a.username);
777	  await writeFpmPool(conn, a.username, home, webroot, a.phpVersion);
778	  await run(conn, "unsuspend: enable vhost", `ln -sfn /etc/nginx/sites-available/hosting-${a.username}.conf /etc/nginx/sites-enabled/hosting-${a.username}.conf; nginx -t && systemctl reload nginx || true`);
779	  await run(conn, "unsuspend: unlock user", `usermod -U ${a.username} 2>/dev/null || true`);
780	}
