133	  // burst, a migrated app's first request — and the kernel kills a process with no
134	  // warning and nothing to fall back on. A RAM-sized swapfile (capped so it never
135	  // eats a small root disk) turns a hard kill into slow-but-alive. Idempotent:
136	  // skips if any swap is already on or /swapfile already exists.
137	  const swapScript = [
138	    "#!/bin/bash",
139	    "# Nxeon: ensure a swapfile exists as an OOM safety net on small-RAM VMs.",
140	    "if swapon --show=NAME --noheadings 2>/dev/null | grep -q .; then exit 0; fi",
141	    "[ -e /swapfile ] && exit 0",
142	    'MEM_MB=$(awk "/MemTotal/{print int(\\$2/1024)}" /proc/meminfo 2>/dev/null || echo 1024)',
143	    "SWAP_MB=$MEM_MB",
144	    '[ "$SWAP_MB" -lt 1024 ] && SWAP_MB=1024',
145	    '[ "$SWAP_MB" -gt 4096 ] && SWAP_MB=4096',
146	    "# Leave >2 GB free on / so the swapfile never fills the root disk.",
147	    'AVAIL_MB=$(df -Pm / | awk "NR==2{print \\$4}")',
