149	    '[ "$SWAP_MB" -lt 256 ] && exit 0',
150	    "fallocate -l ${SWAP_MB}M /swapfile 2>/dev/null || dd if=/dev/zero of=/swapfile bs=1M count=${SWAP_MB} 2>/dev/null || exit 0",
151	    "chmod 600 /swapfile",
152	    "mkswap /swapfile >/dev/null 2>&1 || exit 0",
153	    "swapon /swapfile 2>/dev/null || exit 0",
154	    "grep -q '^/swapfile ' /etc/fstab 2>/dev/null || echo '/swapfile none swap sw 0 0' >> /etc/fstab",
