240	/**
241	 * Allocate a vmid for a brand-new server, refusing any id that still owns backup
242	 * archives from a previous tenant (see `pickProvisionVmid` for the incident).
243	 *
244	 * If the archive listing cannot be read we do NOT silently fall back to the raw
245	 * `nextVmid()` — that is the exact behaviour that leaks a previous tenant's data,
246	 * and a provision that fails is recoverable while a cross-tenant disclosure is
247	 * not. The job retries; an operator sees why.
248	 */
249	async function allocateFreshVmid(conn: any): Promise<number> {
250	  const candidate = await conn.nextVmid();
251	  const archived = await archivedVmids(conn);
252	
253	  // Ids already in use, so skipping forward cannot land on a live VM. Read
254	  // cluster-wide (qemu + lxc); fall back to this node's qemu list.
255	  let taken = new Set<number>();
256	  try {
257	    const res: any[] = await conn.get("/cluster/resources", { type: "vm" });
258	    for (const r of res ?? []) if (Number.isInteger(r?.vmid)) taken.add(r.vmid);
259	  } catch {
260	    const vms: any[] = await conn.get(`/nodes/${conn.node}/qemu`);
261	    taken = new Set((vms ?? []).map((v: any) => Number(v?.vmid)).filter(Number.isInteger));
262	  }
263	
264	  const { vmid, skipped } = pickProvisionVmid({ candidate, takenVmids: taken, archivedVmids: archived });
265	  if (skipped.length > 0) {
266	    console.warn(
267	      `[worker] vmid ${skipped.join(", ")} skipped for provisioning — still holds backup archives ` +
268	        `from a previous server; allocated ${vmid} instead`
269	    );
270	  }
271	  return vmid;
272	}
