274	async function provision(job: Job) {
275	  const server = await loadServer(job);
276	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });
277	
278	  if (SANDBOX) {
279	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
280	    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
281	    const vmid = server.vmid ?? (990000 + (await db.server.count()));
282	    const password = generatePassword();
283	    const ip = sandboxIp(vmid);
284	    await db.server.update({
285	      where: { id: server.id },
286	      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
287	    });
288	    await notify(
289	      server.userId,
290	      `Server ${server.hostname} is ready`,
291	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
292	      `/dashboard/servers/${server.id}`
293	    );
294	    // Post-purchase review request (once per server, skipped if no profiles set).
295	    await sendReviewRequestForServer(server.id);
296	    return;
297	  }
298	
299	  const { conn, row: nodeRow } = await nodeFor(server);
300	  const storage = server.plan.storageTier === "hdd"
301	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
302	    : nodeRow?.storageNvme ?? "vmdata";
303	
304	  // Pick a vmid that does NOT still own a previous tenant's backup archives.
305	  // `/cluster/nextid` hands back the lowest FREE id, and nothing reaps a deleted
306	  // server's vzdump archives, so the id freed by a deletion comes back carrying
307	  // the old owner's backups — which every backup surface then attributes to the
308	  // new customer (listBackups/requestRestore key on vmid alone). See
309	  // `pickProvisionVmid` in lib/proxmox.ts. Only for a FRESH allocation: a retry
310	  // keeps the vmid already persisted on the row.
311	  const vmid = server.vmid ?? (await allocateFreshVmid(conn));
312	  const password = generatePassword();
313	
314	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
315	  // Default: every new server pulls a dedicated IP from the pool; if the pool is
316	  // empty (or OVH isn't configured) it transparently falls back to shared NAT.
317	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
318	  const { getSettingBool: _settingBool } = await import("../lib/settings");
319	  const wantDedicated = server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
320	  if (wantDedicated && ovhConfigured()) {
321	    try {
322	      // Idempotent: on a PROVISION retry (VM may already exist) this returns the
323	      // server's already-ASSIGNED IP rather than claiming a second pool IP.
324	      dedicated = await allocateDedicatedIp(server.id, vmid);
325	    } catch (e) {
326	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
327	    }
328	  }
329	  // Node-aware + transactionally-claimed allocation (passing the server id enables
330	  // the claim path, so two concurrent provisions can't pick the same IP/port).
331	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
332	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));
333	
334	  await db.server.update({
335	    where: { id: server.id },
336	    data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
337	  });
338	
339	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
340	  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
341	  // (worker restart mid-clone, or any transient failure in the steps below) would
342	  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
343	  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
344	  // the clone is idempotent, so skip it when the VM is already present.
345	  let vmAlreadyExists = false;
346	  try {
347	    await conn.vmStatus(vmid);
348	    vmAlreadyExists = true;
349	  } catch {
350	    vmAlreadyExists = false;
351	  }
352	  if (vmAlreadyExists) {
353	    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
354	  } else {
355	    const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
356	      newid: vmid,
357	      name: server.hostname,
358	      full: 1,
359	      storage,
360	    });
361	    await conn.waitForTask(cloneUpid, 600_000);
362	  }
363	
364	  // Per-server cloud-init snippet (base + panel/app install + add-ons).
365	  //
366	  // This write used to be `.catch`'d to a console line (M7 #10). It must not be:
367	  // the very next config POST sets `cicustom: vendor=…/nxeon-<vmid>.yaml`, so a
368	  // failed write hands the VM a vendor-data file that does not exist. Root SSH
369	  // config, the guest agent, the setup script, START-WITH-CLAUDE.md and the MOTD
370	  // all silently vanish, and the customer is still told the server is ready.
371	  // Failing here is recoverable — the job retries, and the clone above is
372	  // idempotent. Continuing is not.
373	  const snippet = buildCloudInit(server);
374	  try {
375	    await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8");
376	  } catch (e: any) {
377	    throw new Error(
378	      `could not write the cloud-init snippet ${SNIPPET_DIR}/nxeon-${vmid}.yaml (${e?.message ?? e}). ` +
379	        `The VM would boot with no root password, no SSH key and no setup script, so provisioning ` +
380	        `stopped here rather than reporting a server that would not be usable.`
381	    );
382	  }
383	
384	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
385	  const sshkeys = keys.length
386	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
387	    : undefined;
388	  const cfg: Record<string, any> = {
389	    cores: server.plan.cpuCores,
390	    memory: server.plan.ramMB,
391	    ciuser: "root",
392	    cipassword: password,
393	    sshkeys,
394	    nameserver: "1.1.1.1 8.8.8.8",
395	    onboot: 1,
396	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
397	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
398	  };
399	  if (dedicated) {
400	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
401	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
402	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
403	  } else {
404	    // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
405	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`;
406	  }
407	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
408	
409	  // Provision at the EFFECTIVE size: the plan's allowance plus any extra disk the
410	  // customer bought as a deploy-time upsell, so the VM is born the right size and
411	  // no separate DISK_EXPAND job is needed on a fresh order.
412	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
413	    disk: "scsi0",
414	    size: `${effectiveDiskGB(server.plan.diskGB, server.extraDiskGB)}G`,
415	  });
416	
417	  // Port forwarding is what makes the `ssh root@host -p <port>` line below true
418	  // for a NAT server. If it cannot be proved, the readiness message says so
419	  // instead of printing a command that will hang (H5 + M7 #10). Not fatal: the
420	  // VM itself is fine and a failed PROVISION would flip it to ERROR and release
421	  // its IP, which is a worse outcome than a missing forward.
422	  let natError: Error | null = null;
423	  if (!SANDBOX && !dedicated) natError = await syncPortForwardsBestEffort(`provision ${server.hostname}`);
424	
425	  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
426	  await conn.waitForTask(startUpid);
427	
428	  // `waitForTask` proves Proxmox accepted the start, nothing more. Ask the guest
429	  // agent whether the machine actually booted before calling it ready (M7 #10).
430	  // A false here is reported, never downgraded into silence.
431	  const booted = SANDBOX ? true : await waitForGuestAgent(conn, conn.node, vmid);
432	
433	  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
434	  const isImage = server.osTemplate.category !== "PLAIN_OS";
435	  const sshLine = dedicated
436	    ? `ssh root@${dedicated.address}`
437	    : `ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`;
438	
439	  const caveats: string[] = [];
440	  if (natError) {
441	    caveats.push(
442	      `Port forwarding could NOT be confirmed for this server, so the SSH command above may not connect yet — ` +
443	        `we are not going to pretend otherwise. Support has been alerted (${natError.message.slice(0, 200)}).`
444	    );
445	  }
446	  if (!booted) {
447	    caveats.push(
448	      "The hypervisor started the VM, but its guest agent has not answered yet, so we cannot confirm the " +
449	        "operating system finished booting. Give it a few more minutes; if the SSH command still fails, open a ticket."
450	    );
451	  }
452	  const body = [
453	    isImage ? `${server.osTemplate.name} is installing in the background (a few minutes). ${sshLine}` : sshLine,
454	    ...caveats,
455	  ].join(" — ");
456	  await notify(
457	    server.userId,
458	    // Never assert "ready" for something we could not verify.
459	    caveats.length ? `Server ${server.hostname} is up, with caveats` : `Server ${server.hostname} is ready`,
460	    body,
461	    `/dashboard/servers/${server.id}`
462	  );
463	  // Post-purchase review request (once per server, skipped if no profiles set).
464	  await sendReviewRequestForServer(server.id);
465	}
