485	/**
486	 * Tear down a VM. Idempotent and verified — see `destroyVmIdempotent` in
487	 * lib/proxmox.ts for the incident and the ladder. The bare version of this
488	 * function threw on an already-absent VM, which is what made a retried REINSTALL
489	 * destroy a customer's server permanently.
490	 */
491	async function destroyVm(conn: any, vmid: number): Promise<DestroyOutcome> {
492	  const host: VmDestroyHost = {
493	    probe: async (id) => {
494	      try {
495	        await conn.vmStatus(id);
496	        return "present";
497	      } catch (e) {
498	        // Only a vmid-anchored "config does not exist" proves absence. Anything
499	        // else (auth, network, a locked node) is genuinely unknown and must not
500	        // be read as "already gone".
501	        return isVmAbsentError(e, id) ? "absent" : "unknown";
502	      }
503	    },
504	    stop: async (id) => {
505	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${id}/status/stop`, {});
506	      await conn.waitForTask(stopUpid);
507	    },
508	    destroy: async (id) => {
509	      const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${id}`, {
510	        "destroy-unreferenced-disks": 1,
511	        purge: 1,
512	      });
513	      await conn.waitForTask(delUpid, 600_000);
514	    },
515	  };
516	  return destroyVmIdempotent(host, vmid);
517	}
