519	async function remove(job: Job) {
520	  const server = await loadServer(job);
521	  const { conn } = await nodeFor(server);
522	  if (!SANDBOX && server.vmid) {
523	    // `destroyVm` is now idempotent and VERIFIES the VM is gone before returning,
524	    // so the absent case no longer needs to be caught here at all. The catch that
525	    // remains is narrowed to this vmid: it used to swallow any error containing
526	    // "does not exist", which also matches `storage 'vmdata' does not exist` and
527	    // `volume ... does not exist` — errors that mean the VM is very much still
528	    // running. On one of those the handler proceeded to delete the Server row and
529	    // every Volume row pinned to it, leaving a live VM with no database record:
530	    // invisible to billing, invisible to the panel, still holding the customer's
531	    // data and impossible to reach through any surface we own.
532	    try {
533	      await destroyVm(conn, server.vmid);
534	    } catch (e: any) {
535	      if (!isVmAbsentError(e, server.vmid)) throw e;
536	    }
537	    // Best-effort: remove the per-server cloud-init snippet
538	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
539	  }
540	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
541	  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
542	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
543	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
544	  // diskName and keep billing forever. Remove them and notify the owner. (The
545	  // reinstall guard already blocks the accidental case; a full server delete is an
546	  // intentional teardown, so we drop the volumes with it.)
547	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
548	  if (orphanVolumes.length > 0) {
549	    await db.volume.deleteMany({ where: { serverId: server.id } });
550	    for (const v of orphanVolumes) {
551	      await notify(
552	        v.userId,
553	        `Volume "${v.name}" was removed`,
554	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
555	        "/dashboard/volumes",
556	      ).catch(() => {});
557	    }
558	  }
559	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
560	  // server.delete cascade removes THIS running Job row — the success-path
561	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
562	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
563	  await db.server.delete({ where: { id: server.id } });
564	  // Best-effort BY NECESSITY: the server row is gone, so a throw here re-queues
565	  // DELETE, which then dies on "Server not found" and the sync is never retried
566	  // (H5's aggravating factor). The failure is logged in full rather than hidden.
567	  if (!SANDBOX) await syncPortForwardsBestEffort(`delete ${server.hostname}`);
568	}
