570	async function reinstall(job: Job) {
571	  const server = await loadServer(job);
572	  if (SANDBOX) {
573	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
574	    await notify(
575	      server.userId,
576	      `Server ${server.hostname} reinstalled (sandbox)`,
577	      "The sandbox server was reinstalled (no real VM was touched).",
578	      `/dashboard/servers/${server.id}`
579	    );
580	    return;
581	  }
582	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
583	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
584	  // EVERY disk the vmid owns, including attached block-storage Volume disks
585	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
586	  // by that vmid, and both purge and the default destroy (which removes disks
587	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
588	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
589	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
590	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
591	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
592	  // can be re-attached after the reinstall. This runs BEFORE any status change or
593	  // destructive call, so a blocked reinstall touches nothing.
594	  //
595	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
596	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
597	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
598	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
599	  // let the worst path through: fill a volume, Detach (the UI says "Data is
600	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
601	  // Detaching is therefore NOT sufficient protection, and telling the customer to
602	  // detach was wrong advice; they must delete the volume (which destroys just
603	  // that disk, deliberately) or move it to another server first.
604	  const pinnedVolumes = await db.volume.findMany({
605	    where: { serverId: server.id },
606	  });
607	  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
608	  const realPinned = pinnedVolumes.filter(
609	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
610	  );
611	  if (realPinned.length > 0) {
612	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
613	    throw new Error(
614	      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
615	        `Reinstalling purges every disk this server owns — including detached volumes ` +
616	        `that are still assigned to it — and that cannot be undone.`
617	    );
618	  }
619	
620	  const { conn } = await nodeFor(server);
621	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
622	  if (server.vmid) await destroyVm(conn, server.vmid);
623	  await provision(job);
624	}
