626	async function suspend(job: Job, unsuspend: boolean) {
627	  const server = await loadServer(job);
628	  if (SANDBOX) {
629	    if (unsuspend) {
630	      await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", suspendedNote: null, suspendReason: null } });
631	    } else {
632	      await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
633	    }
634	    return;
635	  }
636	  const { conn, row: nodeRow } = await nodeFor(server);
637	  if (unsuspend) {
638	    // The dedicated IP was returned to the pool while suspended — re-allocate one
639	    // and reconfigure the public network before starting the VM back up.
640	    if (server.vmid) {
641	      const { getSettingBool: _sb } = await import("../lib/settings");
642	      const wantDedicated = server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
643	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
644	      let reconfigured = alreadyHas ? true : false;
645	      if (wantDedicated && ovhConfigured() && !alreadyHas) {
646	        try {
647	          const d = await allocateDedicatedIp(server.id, server.vmid);
648	          if (d) {
649	            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
650	              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
651	              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
652	            });
653	            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
654	            reconfigured = true;
655	          }
656	        } catch (e) {
657	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; falling back to NAT", e);
658	        }
659	      }
660	      // If we couldn't (or didn't) give it a dedicated IP, its net0 still points at
661	      // the Virtual MAC + failover IP that suspend released back to the pool — that
662	      // IP may now belong to another server. Reconfigure onto shared NAT so it boots
663	      // with a valid, non-conflicting network instead of a dead public config.
664	      if (!reconfigured) {
665	        try {
666	          const ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
667	          const sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
668	          await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
669	            net0: `virtio,bridge=${nodeRow?.bridge ?? "vmbr1"}`,
670	            ipconfig0: `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`,
671	          });
672	          await db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort } });
673	        } catch (e) {
674	          console.error("[worker] NAT fallback on unsuspend failed", e);
675	        }
676	      }
677	    }
678	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null, suspendReason: null } });
679	    // Not fatal to the unsuspend itself (the customer is paid up and the VM must
680	    // come back), but never silent: an unproved sync is logged with its reason.
681	    if (!SANDBOX) await syncPortForwardsBestEffort(`unsuspend ${server.hostname}`);
682	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
683	    await conn.waitForTask(upid);
684	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
685	  } else {
686	    try {
687	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
688	      await conn.waitForTask(upid);
689	    } catch { /* may already be stopped */ }
690	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
691	    if (!SANDBOX) await syncPortForwardsBestEffort(`suspend ${server.hostname}`);
692	    // Return the dedicated IP to the pool while the server is suspended, so it
693	    // can be handed to a paying server. Re-allocated on unsuspend.
694	    if (ovhConfigured()) {
695	      try {
696	        const had = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
697	        if (had) {
698	          await releaseDedicatedIp(server.id);
699	          // MUST also clear the address off the server: `Server.ipAddress` is UNIQUE,
700	          // so leaving the released IP here makes the next server that claims it fail
701	          // with P2002 — that server then silently lands on NAT while its OVH Virtual
702	          // MAC stays allocated and billable. (NAT servers keep their private IP.)
703	          await db.server.update({
704	            where: { id: server.id },
705	            data: { ipAddress: null, ipv6: null },
706	          });
707	        }
708	      } catch (e) {
709	        console.error("[worker] release dedicated IP on suspend failed", e);
710	      }
711	    }
712	  }
713	}
