723	async function resize(job: Job) {
724	  const server = await loadServer(job);
725	  const payload = (job.payload ?? {}) as { planId?: string };
726	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
727	  if (!newPlan) throw new Error("resize: target plan not found");
728	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
729	
730	  // Any separately-purchased extra disk is ADDITIVE to whichever plan the server
731	  // sits on, so it survives the plan change untouched — `Server.extraDiskGB` is
732	  // never written here. Sizes below are therefore always the EFFECTIVE size
733	  // (new plan + extra); using the bare plan size would ask Proxmox to SHRINK the
734	  // disk of any server carrying extra storage, and the resize would hard-fail.
735	  const newTotalDiskGB = effectiveDiskGB(newPlan.diskGB, server.extraDiskGB);
736	  const currentTotalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
737	  const diskLine =
738	    server.extraDiskGB > 0
739	      ? `${newTotalDiskGB} GB disk (${newPlan.diskGB} GB plan + ${server.extraDiskGB} GB added storage)`
740	      : `${newPlan.diskGB} GB disk`;
741	
742	  if (SANDBOX) {
743	    await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
744	    await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
745	      `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${diskLine}`,
746	      `/dashboard/servers/${server.id}`);
747	    return;
748	  }
749	
750	  const { conn } = await nodeFor(server);
751	  const wasRunning = server.status === "RUNNING";
752	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
753	    cores: newPlan.cpuCores,
754	    memory: newPlan.ramMB,
755	  });
756	  if (newTotalDiskGB > currentTotalDiskGB) {
757	    await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
758	      disk: "scsi0",
759	      size: `${newTotalDiskGB}G`,
760	    });
761	  }
762	  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
763	  // CPU/RAM changes need a power cycle to apply
764	  if (wasRunning) {
765	    try {
766	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
767	      await conn.waitForTask(stopUpid, 120_000);
768	    } catch {
769	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
770	      await conn.waitForTask(stopUpid);
771	    }
772	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
773	    await conn.waitForTask(startUpid);
774	  }
775	  await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
776	    `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${diskLine}`,
777	    `/dashboard/servers/${server.id}`);
778	}
