780	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
781	  const server = await loadServer(job);
782	  const payload = (job.payload ?? {}) as { name?: string };
783	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
784	  if (!name) throw new Error("snapshot: invalid name");
785	  if (SANDBOX) {
786	    await notify(
787	      server.userId,
788	      `Snapshot ${op} (sandbox): ${name}`,
789	      `Sandbox snapshot ${op} completed (no real VM was touched).`,
790	      `/dashboard/servers/${server.id}`
791	    );
792	    return;
793	  }
794	  const { conn } = await nodeFor(server);
795	  let upid: string;
796	  if (op === "create") {
797	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
798	  } else if (op === "delete") {
799	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
800	  } else {
801	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
802	  }
803	  await conn.waitForTask(upid, 600_000);
804	  if (op === "rollback") {
805	    // rollback leaves the VM stopped; bring it back if the server should be running
806	    const current = await db.server.findUnique({ where: { id: server.id } });
807	    if (current?.status === "RUNNING") {
808	      try {
809	        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
810	        await conn.waitForTask(startUpid);
