892	/**
893	 * Create one backup and PROVE it exists before saying so.
894	 *
895	 * INCIDENT H4 (2026-07-26 rehearsal): this handler gated only the vzdump task's
896	 * exit status — it never checked that an archive was written, had no failure
897	 * notification, and `Server.lastAutoBackup` was stamped by the SWEEP at enqueue
898	 * time. A customer could read "Last automatic backup: today" every night for a
899	 * month with nothing in storage, and find out at restore time.
900	 *
901	 * Now: snapshot the archive list before the run, re-read it after, and require a
902	 * volid that was not there and is not empty (`freshBackupProof`). Only that
903	 * writes `lastAutoBackup`. A failure notifies the customer with the reason and a
904	 * command, rather than leaving a stale-but-cheerful timestamp behind.
905	 */
906	async function backupCreate(job: Job) {
907	  const server = await loadServer(job);
908	  if (SANDBOX) {
909	    await sandboxAnimateJob(job.id, [
910	      { pct: 5, step: "Starting" },
911	      { pct: 25, step: "Creating archive… 25%" },
912	      { pct: 55, step: "Creating archive… 55%" },
913	      { pct: 80, step: "Creating archive… 80%" },
914	      { pct: 95, step: "Finalizing" },
915	      { pct: 100, step: "Backup complete" },
916	    ]);
917	    // Deliberately NOT stamping lastAutoBackup here: no archive exists, and the
918	    // column means "a backup was observed in storage".
919	    await notify(
920	      server.userId,
921	      `Backup simulated (sandbox) for ${server.hostname}`,
922	      "Sandbox only — no VM was contacted and no archive was written. This is not a restore point.",
923	      `/dashboard/servers/${server.id}`
924	    );
925	    return;
926	  }
927	  if (server.vmid == null) {
928	    throw new Error("backup: this server has no VMID yet, so there is nothing to back up.");
929	  }
930	  const vmid = server.vmid;
931	
932	  try {
933	    await reportJobProgress(job.id, 2, "Starting");
934	    const { conn } = await nodeFor(server);
935	
936	    // Snapshot what already exists. Membership of this set — not a timestamp
937	    // comparison — is what makes "a new archive appeared" unarguable: ctime comes
938	    // off the hypervisor and our window would come off the worker's clock.
939	    const before = await listBackupsOn(conn, vmid);
940	
941	    const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
942	      vmid,
943	      storage: "backup",
944	      mode: "snapshot",
945	      compress: "zstd",
946	    });
947	    await waitForTaskProgress(
948	      conn,
949	      upid,
950	      (progress, step) => reportJobProgress(job.id, progress, step),
951	      { timeoutMs: 3_600_000, phase: "backup" }
952	    );
953	
954	    await reportJobProgress(job.id, 96, "Verifying archive");
955	    const after = await listBackupsOn(conn, vmid);
956	    const proof = freshBackupProof({ vmid, before, after });
957	    if (!proof.proven) throw new Error(`backup not verified — ${proof.reason}`);
958	
959	    await reportJobProgress(job.id, 100, "Backup complete");
960	
961	    // Retention: keep the latest N backups for this server (N = the paid backup
962	    // tier's keep count, an explicit backupKeep override winning); prune the rest.
963	    const keep = resolveBackupKeep(server.backupTier, server.backupKeep);
964	    try {
965	      const pruned = await pruneBackups(conn, vmid, keep);
966	      if (pruned > 0) console.log(`[backup] pruned ${pruned} old backup(s) for vmid ${vmid} (keep ${keep})`);
967	    } catch (e) {
968	      console.error(`[backup] prune failed for vmid ${vmid}`, e);
969	    }
970	
971	    // The ONLY writer of lastAutoBackup, and only on proof.
972	    await db.server.update({ where: { id: server.id }, data: { lastAutoBackup: new Date() } });
973	
974	    await notify(
975	      server.userId,
976	      `Backup completed for ${server.hostname}`,
977	      `Verified present in backup storage: ${proof.volid} (${humanBytes(proof.sizeBytes)}).`,
978	      `/dashboard/servers/${server.id}`
979	    );
980	  } catch (e: any) {
981	    // Tell the customer it broke. Only on the final attempt, so the worker's
982	    // three retries do not produce three notifications for one bad night.
983	    if (job.attempts >= MAX_ATTEMPTS) {
984	      await notify(
985	        server.userId,
986	        `Backup FAILED for ${server.hostname}`,
987	        `${String(e?.message ?? e).slice(0, 400)} — this server has no new restore point. ` +
988	          `Your last verified backup (if any) is shown under Backups.`,
989	        `/dashboard/servers/${server.id}`
990	      );
991	    }
992	    throw e;
993	  }
994	}
