476	/** The higher plans an account may move UP to (never a downgrade): active plans
477	 *  priced at-or-above and disk at-or-above the current plan, and strictly larger
478	 *  in at least one, excluding the current plan. Owner or admin. */
479	export async function listHostingUpgradePlans(accountId: string): Promise<{ currentPlanName?: string; plans?: UpgradePlanView[]; error?: string }> {
480	  const user = await requireUser();
481	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
482	  if (!a) return { error: "Account not found." };
483	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
484	  const cur = a.plan;
485	  const all = await db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
486	  const plans = all
487	    .filter((p) => p.id !== cur.id && p.priceCents >= cur.priceCents && p.diskGB >= cur.diskGB && (p.priceCents > cur.priceCents || p.diskGB > cur.diskGB))
488	    .map((p) => ({
489	      id: p.id, name: p.name, priceCents: p.priceCents, diskGB: p.diskGB, maxSites: p.maxSites,
490	      maxDatabases: p.maxDatabases, bandwidthTB: p.bandwidthTB, tagline: p.tagline,
491	      deltaCents: Math.max(0, p.priceCents - cur.priceCents),
492	    }));
493	  return { currentPlanName: cur.name, plans };
494	}
