716	export async function createSubdomain(accountId: string, label: string): Promise<HostingResult> {
717	  const ctx = await ownedSiteAccount(accountId);
718	  if ("error" in ctx) return { error: ctx.error };
719	  const { a } = ctx;
720	  const clean = String(label ?? "").trim().toLowerCase();
721	  if (!isValidSubdomainLabel(clean)) return { error: "Enter a valid subdomain label — letters, digits and hyphens only." };
722	  const fqdn = `${clean}.${a.primaryDomain}`;
723	  if (!isValidHostingDomain(fqdn)) return { error: "That subdomain isn’t a valid hostname." };
724	  // Reject if another tenant already claimed this exact hostname as an addon domain
725	  // (or primary). fqdn @unique blocks subdomain↔subdomain; this closes the addon
726	  // path (audit HIGH-1, reverse direction).
727	  if (await isHostnameClaimed(fqdn)) {
728	    return { error: "That hostname is already in use on Nxeon." };
729	  }
730	  const { docroot } = subdomainPaths(a.username, clean);
731	  try {
732	    await db.$transaction(async (tx) => {
733	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
734	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
735	      if (subs + addons >= a.maxSites) throw new Error("CAP");
736	      const sub = await tx.hostingSubdomain.create({ data: { accountId: a.id, label: clean, fqdn, docroot, status: "PENDING" } });
737	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_SUBDOMAIN", payload: JSON.stringify({ subdomainId: sub.id }) } });
738	    }, { isolationLevel: "Serializable" });
739	  } catch (e) {
740	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
741	    return { error: "That subdomain already exists, or the request raced — try again." };
742	  }
743	  revalidatePath(`/dashboard/hosting/${accountId}`);
744	  return { ok: true };
745	}
