const ENABLED = process.env.ENABLE_SHARED_HOSTING === "1";
const CONNECT_TIMEOUT_MS = 20_000;
const STEP_TIMEOUT_MS = 60_000;
/** Node hardening runs the whole onboard script (apt installs — ModSecurity,
 *  ClamAV — take minutes), so it gets a much longer ceiling than a single step. */
const HARDEN_TIMEOUT_MS = 15 * 60_000;
/** Keep the TAIL of the onboard output as the stored log (the end carries the
 *  final status + any failure), capped so a chatty run can't bloat the row. */
const HARDEN_LOG_MAX = 8000;

// ---- Node hardening sweep (admin "Run setup / harden") ---------------------

/**
 * Run `scripts/onboard-hosting-node.sh` on ONE admin-QUEUED node over the
 * platform's EXISTING SSH path (the node's stored encrypted root password, the
 * same credential the account provisioner already uses). This lets the owner
 * harden a node — ModSecurity WAF + ClamAV + the hardening steps — WITHOUT ever
 * knowing the node's root password. The onboard script is idempotent and
 * `nginx -t`-guarded, so a re-run is safe and can't reload a broken config.
 *
 * NOT gated on ENABLE_SHARED_HOSTING: hardening is preparatory work that should
 * run before selling is switched on. Only the SANDBOX branch differs — there is
 * no real box to SSH into, so it just simulates the result. The sweep NEVER
 * hardens on its own initiative: it only acts on a node an admin explicitly set
 * to QUEUED (via adminHardenHostingNode).
 */
export async function hostingNodeHardenSweep(): Promise<void> {
  if (SANDBOX) {
    // No real SSH in sandbox — mark every queued node done so staging can drive
    // the whole button → badge → log flow without a box.
    const queued = await db.hostingNode.findMany({ where: { hardenStatus: "QUEUED" }, select: { id: true } });
    for (const n of queued) {
      await db.hostingNode
        .update({ where: { id: n.id }, data: { hardenStatus: "DONE", hardenedAt: new Date(), hardenLog: "[sandbox] onboard script simulated" } })
        .catch(() => undefined);
    }
    return;
  }

  // One node per tick, oldest QUEUED first — the run is minutes long, so we
  // don't want to hold several SSH sessions open at once.
  const node = await db.hostingNode.findFirst({ where: { hardenStatus: "QUEUED" }, orderBy: { createdAt: "asc" } });
  if (!node) return;
  // Claim it immediately so the next tick can't pick the same node up again.
  await db.hostingNode.update({ where: { id: node.id }, data: { hardenStatus: "RUNNING" } });

  try {
    // The worker's WorkingDirectory is the app root, so the script sits alongside.
    const script = readFileSync(join(process.cwd(), "scripts/onboard-hosting-node.sh"), "utf8");
    // Base64 the whole script and reconstitute it on the node — no quoting/heredoc
    // hazard reaches the shell, and the payload is a single opaque token.
    const b64 = Buffer.from(script, "utf8").toString("base64");
    const conn = await connectNode(node);
    try {
      // Decode → run → capture rc → always remove the temp script → exit with rc,
      // so a non-zero onboard exit is faithfully reported as FAILED. 2>&1 folds
      // stderr into the captured combined `out`.
      const cmd =
        `set -o pipefail; printf %s '${b64}' | base64 -d > /root/.nxeon-onboard.sh && ` +
        `bash /root/.nxeon-onboard.sh 2>&1; rc=$?; rm -f /root/.nxeon-onboard.sh; exit $rc`;
      const { code, out } = await exec(conn, cmd, HARDEN_TIMEOUT_MS);
      await db.hostingNode.update({
        where: { id: node.id },
        data: {
          hardenStatus: code === 0 ? "DONE" : "FAILED",
          hardenedAt: new Date(),
          hardenLog: out.slice(-HARDEN_LOG_MAX),
        },
      });
    } finally {
      try { conn.end(); } catch { /* */ }
    }
  } catch (e) {
    // Any SSH/read/timeout error must leave a terminal state — never a node stuck
    // in RUNNING (which the action-level guard would then refuse to re-queue).
    await db.hostingNode
      .update({
        where: { id: node.id },
        data: { hardenStatus: "FAILED", hardenedAt: new Date(), hardenLog: (e instanceof Error ? e.message : String(e)).slice(-HARDEN_LOG_MAX) },
      })
      .catch(() => undefined);
  }
}

// ---- Serve-verification + self-heal health sweep ---------------------------

