"use client";

import { useActionState, useEffect, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import {
  adminCreateHostingPlan,
  adminToggleHostingPlan,
  adminCreateHostingNode,
  adminToggleHostingNode,
  adminHardenHostingNode,
} from "@/lib/actions-hosting";
import { recommendHostingPlan } from "@/lib/hosting/recommend";

const money = (c: number) => `$${(c / 100).toFixed(2)}`;

type Plan = { id: string; slug: string; name: string; priceCents: number; diskGB: number; maxSites: number; maxDatabases: number; bandwidthTB: number; active: boolean };
type Node = {
  id: string; name: string; publicIp: string; status: string; enabled: boolean; used: number; maxAccounts: number;
  hardenStatus: string; hardenedAt: string | null; hardenLog: string | null;
};

/** A node whose hardening run is still in flight — used to drive the auto-poll. */
const IN_FLIGHT = (s: string) => s === "QUEUED" || s === "RUNNING";

function HardenBadge({ status }: { status: string }) {
  const map: Record<string, { label: string; cls: string }> = {
    NONE: { label: "not hardened", cls: "text-slate-500" },
    QUEUED: { label: "queued", cls: "text-amber-300" },
    RUNNING: { label: "running…", cls: "text-sky-300" },
    DONE: { label: "hardened", cls: "text-emerald-300" },
    FAILED: { label: "failed", cls: "text-red-400" },
  };
  const m = map[status] ?? map.NONE;
  return <span className={`text-xs font-medium ${m.cls}`}>{m.label}</span>;
}

function HardenCell({ node }: { node: Node }) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [showLog, setShowLog] = useState(false);
  const busy = IN_FLIGHT(node.hardenStatus) || pending;

  const run = () => {
    setError(null);
    startTransition(async () => {
      const res = await adminHardenHostingNode(node.id);
      if (res?.error) setError(res.error);
      else router.refresh();
    });
  };

  return (
    <div className="space-y-1">
      <div className="flex items-center gap-2">
        <HardenBadge status={node.hardenStatus} />
        {node.hardenStatus === "DONE" && node.hardenedAt && (
          <span className="text-[11px] text-slate-500">{new Date(node.hardenedAt).toLocaleString()}</span>
        )}
      </div>
      <div className="flex items-center gap-3">
        <button type="button" onClick={run} disabled={busy} className="text-xs text-brand-300 hover:underline disabled:opacity-40 disabled:no-underline">
          {busy ? "Working…" : node.hardenStatus === "DONE" || node.hardenStatus === "FAILED" ? "Re-run harden" : "Run setup / harden"}
        </button>
        {node.hardenLog && (
          <button type="button" onClick={() => setShowLog((v) => !v)} className="text-xs text-slate-400 hover:underline">
            {showLog ? "Hide log" : "View log"}
          </button>
        )}
      </div>
      {error && <div className="text-[11px] text-red-400">{error}</div>}
      {showLog && node.hardenLog && (
        <pre className="mt-1 max-h-64 max-w-[520px] overflow-auto rounded-lg border border-white/10 bg-black/40 p-2 font-mono text-[11px] leading-relaxed text-slate-300 whitespace-pre-wrap">
          {node.hardenLog}
        </pre>
      )}
    </div>
  );
}

export function HostingInfra({ plans, nodes }: { plans: Plan[]; nodes: Node[] }) {
  const [planState, planAction, planPending] = useActionState(adminCreateHostingPlan, {} as { error?: string; ok?: boolean });
  const [nodeState, nodeAction, nodePending] = useActionState(adminCreateHostingNode, {} as { error?: string; ok?: boolean });
  const router = useRouter();

  // While any node is QUEUED/RUNNING, refresh the server component every ~5s so
  // the badge + timestamp + log update as the worker sweep progresses. The
  // interval clears itself the moment nothing is in flight.
  const anyInFlight = nodes.some((n) => IN_FLIGHT(n.hardenStatus));
  useEffect(() => {
    if (!anyInFlight) return;
    const t = setInterval(() => router.refresh(), 5000);
    return () => clearInterval(t);
  }, [anyInFlight, router]);

  return (
    <div className="space-y-8">
      {/* Plans */}
      <section className="space-y-3">
        <h2 className="font-semibold">Hosting plans</h2>
        <form action={planAction} className="grid grid-cols-2 gap-3 sm:grid-cols-4">
          {planState?.error && <div className="col-span-full rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{planState.error}</div>}
          {planState?.ok && <div className="col-span-full rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">Plan created.</div>}
          <div><label className="label">Slug</label><input className="input" name="slug" placeholder="starter" required /></div>
          <div><label className="label">Name</label><input className="input" name="name" placeholder="Starter Hosting" required /></div>
          <div><label className="label">Price (cents/mo)</label><input className="input" name="priceCents" type="number" min={0} placeholder="299" required /></div>
          <div><label className="label">Disk (GB)</label><input className="input" name="diskGB" type="number" min={1} placeholder="10" required /></div>
          <div><label className="label">Max sites</label><input className="input" name="maxSites" type="number" min={1} placeholder="1" /></div>
          <div><label className="label">Max databases</label><input className="input" name="maxDatabases" type="number" min={0} placeholder="1" /></div>
          <div className="col-span-full"><button className="btn-primary" disabled={planPending}>{planPending ? "Creating…" : "Create plan"}</button></div>
        </form>
        {plans.length > 0 && (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="text-left text-xs text-slate-500"><tr><th className="py-1">Plan</th><th>Price</th><th>Disk</th><th>Sites/DBs</th><th>Recommended for</th><th>Status</th><th></th></tr></thead>
              <tbody>
                {plans.map((p) => {
                  const rec = recommendHostingPlan(p);
                  return (
                    <tr key={p.id} className="border-t border-white/5 align-top">
                      <td className="py-1.5">{p.name} <span className="text-xs text-slate-500">{p.slug}</span></td>
                      <td>{money(p.priceCents)}/mo</td>
                      <td>{p.diskGB} GB</td>
                      <td>{p.maxSites}/{p.maxDatabases}</td>
                      <td className="max-w-[260px] text-xs text-slate-400">
                        <span className="font-medium text-slate-300">{rec.tier}</span> — {rec.headline}
                      </td>
                      <td>{p.active ? <span className="text-emerald-300">active</span> : <span className="text-slate-500">off</span>}</td>
                      <td className="text-right"><form action={adminToggleHostingPlan.bind(null, p.id)}><button className="text-xs text-brand-300 hover:underline">{p.active ? "Disable" : "Enable"}</button></form></td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </section>

      {/* Nodes */}
      <section className="space-y-3">
        <h2 className="font-semibold">Shared-hosting nodes</h2>
        <p className="text-xs text-slate-500">
          The box customer accounts live on. Its public IP is the shared A-record target every domain points at. Use
          <span className="font-medium text-slate-300"> Run setup / harden</span> to run
          <span className="font-mono"> scripts/onboard-hosting-node.sh</span> on it over Nxeon&apos;s own SSH (ModSecurity WAF + ClamAV + hardening; idempotent). The provisioner stays inert until
          <span className="font-mono"> ENABLE_SHARED_HOSTING=1</span> after a security review.
        </p>
        <form action={nodeAction} className="grid grid-cols-2 gap-3 sm:grid-cols-4">
          {nodeState?.error && <div className="col-span-full rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{nodeState.error}</div>}
          {nodeState?.ok && <div className="col-span-full rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">Node added.</div>}
          <div><label className="label">Name</label><input className="input" name="name" placeholder="shared-1" required /></div>
          <div><label className="label">Public IP</label><input className="input" name="publicIp" placeholder="203.0.113.7" required /></div>
          <div><label className="label">SSH host</label><input className="input" name="sshHost" placeholder="(defaults to public IP)" /></div>
          <div><label className="label">SSH port</label><input className="input" name="sshPort" type="number" placeholder="22" /></div>
          <div><label className="label">Root password</label><input className="input" name="rootPassword" type="password" placeholder="encrypted at rest" /></div>
          <div><label className="label">FQDN (CNAME target)</label><input className="input" name="hostnameFqdn" placeholder="srv1.nxeon.cloud" /></div>
          <div><label className="label">Max accounts</label><input className="input" name="maxAccounts" type="number" placeholder="200" /></div>
          <div className="col-span-full"><button className="btn-primary" disabled={nodePending}>{nodePending ? "Adding…" : "Add node"}</button></div>
        </form>
        {nodes.length > 0 && (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="text-left text-xs text-slate-500"><tr><th className="py-1">Node</th><th>Public IP</th><th>Accounts</th><th>Status</th><th>Hardening</th><th></th></tr></thead>
              <tbody>
                {nodes.map((n) => (
                  <tr key={n.id} className="border-t border-white/5 align-top">
                    <td className="py-1.5">{n.name}</td>
                    <td className="font-mono text-xs">{n.publicIp}</td>
                    <td>{n.used}/{n.maxAccounts}</td>
                    <td>{n.enabled ? <span className="text-emerald-300">{n.status.toLowerCase()}</span> : <span className="text-slate-500">disabled</span>}</td>
                    <td className="py-1.5"><HardenCell node={n} /></td>
                    <td className="text-right"><form action={adminToggleHostingNode.bind(null, n.id)}><button className="text-xs text-brand-300 hover:underline">{n.enabled ? "Disable" : "Enable"}</button></form></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </div>
  );
}

